select date_format(last_restock, 'yyyy-MM') as last_restock_month, case when year(last_restock) < 2024 then 'before_2024' when year(last_restock) = 2024 then '2024' else 'after_2024' end as last_restock_cohort, avg(quantity) as avg_quantity from inventory group by date_format(last_restock, 'yyyy-MM'), case when year(last_restock) < 2024 then 'before_2024' when year(last_restock) = 2024 then '2024' else 'after_2024' end order by last_restock_cohort asc;
